export function buildEvictionsSchedule(startISO = null) {
  return buildScheduleFor(EVICTIONS_MODULES, startISO, EVICTIONS_META.cadenceDays);
}

export function evictionsProgressSummary(progress = {}) {
  return progressSummaryFor(EVICTIONS_MODULES, progress);
}

export function exportEvictionsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: EVICTIONS_META,
    modules: buildEvictionsSchedule(startISO),
    sessionFlow: EVICTIONS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function evictionsRefs() {
  const seen = new Set();
  for (const m of EVICTIONS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((EVICTIONS_META.wordFirst && EVICTIONS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

